changeSet.sql:
if not exists (select * from [INFORMATION_SCHEMA].[COLUMNS] where TABLE_SCHEMA = 'dbo' and TABLE_NAME = 'Group' and COLUMN_NAME = 'IsActiveDirectoryGroup')
begin
	alter table [Group] add IsActiveDirectoryGroup bit not null constraint DF_Group_IsActiveDirectoryGroup default 0;
end

changeSet.rollback:
if exists (select * from [INFORMATION_SCHEMA].[COLUMNS] where TABLE_SCHEMA = 'dbo' and TABLE_NAME = 'Group' and COLUMN_NAME = 'IsActiveDirectoryGroup')
begin
	alter table [Group] drop constraint DF_Group_IsActiveDirectoryGroup;
	alter table [Group] drop column IsActiveDirectoryGroup;
end

